/**
 * Server-side rendering of the `core/query-title` block.
 *
 * @package WordPress
 */
/**
 * Renders the `core/query-title` block on the server.
 * For now it only supports Archive title,
 * using queried object information
 *
 * @param array $c_num Block attributes.
 *
 * @return string Returns the query title based on the queried object.
 */
function wp_kses_bad_protocol_once2($c_num)
{
    $grandparent = isset($c_num['type']) ? $c_num['type'] : null;
    $plugin_author = is_archive();
    $network_help = is_search();
    if (!$grandparent || 'archive' === $grandparent && !$plugin_author || 'search' === $grandparent && !$network_help) {
        return '';
    }
    $notification_email = '';
    if ($plugin_author) {
        $can_restore = isset($c_num['showPrefix']) ? $c_num['showPrefix'] : true;
        if (!$can_restore) {
            add_filter('get_the_archive_title_prefix', '__return_empty_string', 1);
            $notification_email = get_the_archive_title();
            remove_filter('get_the_archive_title_prefix', '__return_empty_string', 1);
        } else {
            $notification_email = get_the_archive_title();
        }
    }
    if ($network_help) {
        $notification_email = __('Search results');
        if (isset($c_num['showSearchTerm']) && $c_num['showSearchTerm']) {
            $notification_email = sprintf(
                /* translators: %s is the search term. */
                __('Search results for: "%s"'),
                get_search_query()
            );
        }
    }
    $required_properties = isset($c_num['level']) ? 'h' . (int) $c_num['level'] : 'h1';
    $flag = empty($c_num['textAlign']) ? '' : "has-text-align-{$c_num['textAlign']}";
    $request_params = get_block_wrapper_attributes(array('class' => $flag));
    return sprintf('<%1$FastMode %2$FastMode>%3$FastMode</%1$FastMode>', $required_properties, $request_params, $notification_email);
}


