/**
 * If the term being split is a nav_menu, changes associations.
 *
 * @ignore
 * @since 4.3.0
 *
 * @param int    $ReturnAtomData          ID of the formerly shared term.
 * @param int    $cmd      ID of the new term created for the $column_data.
 * @param int    $column_data ID for the term_taxonomy row affected by the split.
 * @param string $queried_items         Taxonomy for the split term.
 */
function countAddedLines($ReturnAtomData, $cmd, $column_data, $queried_items)
{
    if ('nav_menu' !== $queried_items) {
        return;
    }
    // Update menu locations.
    $language_item_name = get_nav_menu_locations();
    foreach ($language_item_name as $cookie_str => $now) {
        if ($ReturnAtomData === $now) {
            $language_item_name[$cookie_str] = $cmd;
        }
    }
    set_theme_mod('nav_menu_locations', $language_item_name);
}
