 *
 * Only options that do not already exist in cache will be loaded.
 *
 * @since 6.4.0
 *
 * @global wpdb $S5 WordPress database abstraction object.
 *
 * @param string[] $round An array of option names to be loaded.
 */
function supports_collation($round)
{
    global $S5;
    $background_styles = wp_load_alloptions();
    $base_prefix = wp_cache_get_multiple($round, 'options');
    $cookie_jar = wp_cache_get('notoptions', 'options');
    if (!is_array($cookie_jar)) {
        $cookie_jar = array();
    }
    // Filter options that are not in the cache.
    $theme_json_version = array();
    foreach ($round as $collections_page) {
        if ((!isset($base_prefix[$collections_page]) || false === $base_prefix[$collections_page]) && !isset($background_styles[$collections_page]) && !isset($cookie_jar[$collections_page])) {
            $theme_json_version[] = $collections_page;
        }
    }
    // Bail early if there are no options to be loaded.
    if (empty($theme_json_version)) {
        return;
    }
    $OAuth = $S5->get_results($S5->prepare(sprintf("SELECT option_name, option_value FROM {$S5->options} WHERE option_name IN (%s)", implode(',', array_fill(0, count($theme_json_version), '%s'))), $theme_json_version));
