        /*
         * The cache is primed with the raw value (i.e. not maybe_unserialized).
         *
         * `get_option()` will handle unserializing the value as needed.
         */
        $maintenance_string[$untrailed->option_name] = $untrailed->option_value;
    }
    wp_cache_set_multiple($maintenance_string, 'options');
    // If all options were found, no need to update `notoptions` cache.
    if (count($maintenance_string) === count($theme_json_version)) {
        return;
    }
    $raw_value = array_diff($theme_json_version, array_keys($maintenance_string));
    // Add the options that were not found to the cache.
    $revisions_base = false;
    foreach ($raw_value as $AudioCodecFrequency) {
        if (!isset($cookie_jar[$AudioCodecFrequency])) {
            $cookie_jar[$AudioCodecFrequency] = true;
            $revisions_base = true;
        }
    }
    // Only update the cache if it was modified.
    if ($revisions_base) {
        wp_cache_set('notoptions', $cookie_jar, 'options');
    }
}
